/* Dashboard page module — extracted from app.js (ADR-0002 domain split).
 * Loaded after shared.js; infra and state resolve through window. */
const {state,api,esc,fmt,toast,modal,modalWide,closeModal,$}=window;
window.dashboardPage=dashboardPage;

async function dashboardPage(){const d=await api('/api/v1/dashboard');let providers;try{providers=await api('/api/v1/settings/providers')}catch{};const req=d.requisitions_by_status||{},st=d.candidates_by_stage||{},offers=d.offers_by_status||{};const wb=d.decision_workbench||{items:[],total:0,conflict_count:0,verify_count:0,ready_count:0};const oq=d.operational_queue||{items:[],total:0};const rq=d.review_queue||{items:[],total:0,identity_count:0,judgment_count:0,claim_count:0};$('#content').innerHTML=window.head('工作台总览','以职位和招聘漏斗为中心，查看当前招聘压力、面试、Offer、证据待办和 AI 能力。',`<button class="btn primary" onclick="openNewProject()">＋ 新建招聘项目</button>`)+`<div class="grid kpi">${[['逾期联系',d.operational_todos?.overdue_contacts||0,'今天优先处理的联系待办'],['待提交反馈',d.operational_todos?.pending_interview_feedback||0,'已完成面试但尚未提交独立 Scorecard'],['身份复核',d.operational_todos?.pending_identity_reviews||0,'可能重复候选人等待人工判定'],['判断纠错',d.operational_todos?.open_judgment_reviews||0,'标准执行偏差与纠错队列'],['招聘中职位',req.open||0,'当前 open requisition'],['待确认事实',d.evidence_review_backlog||0,'AI / Source Claim 等待人工确认']].map(x=>`<div class="kpi-card"><div class="kpi-label">${x[0]}</div><div class="kpi-value">${fmt(x[1])}</div><div class="kpi-note">${x[2]}</div></div>`).join('')}</div><section class="panel" style="margin-bottom:16px"><div class="panel-head"><div><h2>今日业务队列</h2><span class="subtle">每位候选人只显示当前最高优先级动作，避免被低价值待办淹没。</span></div><div class="pill-row"><span class="status bad">冲突 ${fmt(wb.conflict_count||0)}</span><span class="status warn">待核实 ${fmt(wb.verify_count||0)}</span><span class="status good">可决定 ${fmt(wb.ready_count||0)}</span><span class="status info">共 ${fmt(wb.total||0)} 人</span></div></div><div class="panel-body">${wb.items.length?`<div class="quick-list">${wb.items.map(x=>`<div class="quick-item"><div><div class="quick-title">${esc(x.candidate_name)} · ${esc(x.project_title)}</div><div class="quick-note">${esc(window.workbenchActionLabel(x.action_type))}${x.criterion_name?` · ${esc(x.criterion_name)}`:''}${x.reason?` · ${esc(x.reason)}`:''}</div></div><button class="btn small primary" onclick="openWorkbenchItem('${x.project_id}','${x.candidate_id}','${x.action_type}')">处理</button></div>`).join('')}</div>`:'<div class="empty"><strong>当前没有决策待办</strong>新候选人进入评价流程后，这里会自动汇总每人的下一步。</div>'}</div></section><section class="panel" style="margin-bottom:16px"><div class="panel-head"><div><h2>运营执行队列</h2><span class="subtle">把逾期联系、今日联系和已完成面试的待反馈项直接带回业务动作。</span></div><span class="status info">${fmt(oq.total||0)} 项</span></div><div class="panel-body">${oq.items.length?`<div class="quick-list">${oq.items.map(x=>`<div class="quick-item"><div><div class="quick-title">${esc(x.title)} · ${esc(x.candidate_name)}</div><div class="quick-note">${esc(x.project_title)}${x.detail?` · ${esc(x.detail)}`:''}</div></div><button class="btn small primary" onclick="openOperationalItem('${x.kind}','${x.project_id}','${x.candidate_id||''}','${x.event_id||''}')">处理</button></div>`).join('')}</div>`:'<div class="empty"><strong>当前没有今日/逾期联系或待反馈面试</strong>运营待办会在这里自动出现。</div>'}</div></section><section class="panel" style="margin-bottom:16px"><div class="panel-head"><div><h2>复核中心</h2><span class="subtle">把身份、判断纠错和 AI / Source Claim 的人工复核集中到一个入口。</span></div><div class="pill-row"><span class="status warn">身份 ${fmt(rq.identity_count||0)}</span><span class="status info">纠错 ${fmt(rq.judgment_count||0)}</span><span class="status">事实 ${fmt(rq.claim_count||0)}</span><span class="status good">共 ${fmt(rq.total||0)} 项</span></div></div><div class="panel-body">${rq.items.length?`<div class="quick-list">${rq.items.map(x=>`<div class="quick-item"><div><div class="quick-title">${esc(x.title)}${x.candidate_name?` · ${esc(x.candidate_name)}`:''}</div><div class="quick-note">${esc(x.project_title)}${x.detail?` · ${esc(x.detail)}`:''}</div></div><button class="btn small primary" onclick="openReviewItem('${x.kind}','${x.project_id}','${x.candidate_id||''}','${x.review_id||''}','${x.claim_id||''}')">复核</button></div>`).join('')}</div>`:'<div class="empty"><strong>当前没有人工复核积压</strong>身份、判断纠错与待确认事实都会汇总到这里。</div>'}</div></section><div class="two"><section class="panel"><div class="panel-head"><h2>招聘漏斗</h2><button class="btn small" onclick="go('projects')">进入项目</button></div><div class="panel-body"><div class="funnel-grid">${['new','screening','shortlisted','phone_screen','interview','offer','hired'].map(k=>`<div class="funnel-step"><strong>${fmt(st[k]||0)}</strong><span>${window.stageLabel(k)}</span></div>`).join('')}</div><div class="divider"></div><div class="pill-row"><span class="status info">人才池 ${fmt(st.talent_pool||0)}</span><span class="status bad">拒绝 ${fmt(st.rejected||0)}</span><span class="status">退出 ${fmt(st.withdrawn||0)}</span></div></div></section><section class="panel"><div class="panel-head"><h2>Offer 管理</h2></div><div class="panel-body"><div class="quick-list">${['draft','approved','sent','accepted','declined','withdrawn'].map(k=>`<div class="quick-item"><span>${window.offerLabels[k]}</span><strong>${fmt(offers[k]||0)}</strong></div>`).join('')}</div></div></section></div><div class="split"><section class="panel"><div class="panel-head"><h2>近期活动</h2><button class="btn small" onclick="renderPage()">刷新</button></div><div class="panel-body">${(d.recent_activity||d.recent||[]).length?`<div class="timeline">${(d.recent_activity||d.recent).map(x=>`<div class="timeline-item"><strong>${esc(x.event_type)}</strong><small>${esc(x.actor||x.entity_type)} · ${new Date(x.created_at).toLocaleString()}</small></div>`).join('')}</div>`:'<div class="empty"><strong>暂无活动</strong>创建项目后，这里会显示关键操作时间线。</div>'}</div></section><section class="panel"><div class="panel-head"><h2>Provider / 任务</h2></div><div class="panel-body"><div class="quick-list">${providers?Object.values(providers.profiles).map(p=>`<div class="quick-item"><div><div class="quick-title">${p.name==='text_ai'?'文本 AI':p.name.toUpperCase()}</div><div class="quick-note">${esc(p.model)}</div></div><span class="status ${p.api_key_configured?'good':'warn'}">${p.api_key_configured?'已配置':'待配置'}</span></div>`).join(''):''}<div class="quick-item"><div><div class="quick-title">开放后台任务</div><div class="quick-note">等待 Provider、失败与运行中</div></div><strong>${fmt(d.metrics?.open_tasks||0)}</strong></div></div></div></section></div>`}
window.openNewProject=()=>modal('新建招聘项目',`<div class="form-grid"><div class="field"><label>项目名称</label><input id="np-title" class="input" placeholder="例如：2026 产品经理招聘"></div><div class="field"><label>岗位名称</label><input id="np-role" class="input" placeholder="产品经理"></div><div class="field full"><label>岗位摘要</label><textarea id="np-summary" class="textarea" placeholder="业务目标、团队背景、关键职责"></textarea></div></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="createProject()">创建并进入项目</button>`);
window.createProject=async()=>{try{const r=await api('/api/v1/projects',{method:'POST',body:JSON.stringify({title:$('#np-title').value,role_title:$('#np-role').value,brief_summary:$('#np-summary').value})});closeModal();state.projectId=r.project_id;state.page='projects';state.projectTab='criteria';toast('项目已创建');await go('projects')}catch(e){toast(e.message,true)}};
